        with pytest.raises(ValueError, match="datetime"):
            svc.create("t", due_at="2025-01-01")  # type: ignore[arg-type]

    def test_normalizes_tags(self, svc, repo):
        task = svc.create("t", tags=["Work", "  WORK  ", "home"])
        # dedup by normalized name
        assert [t.name for t in task.tags] == ["work", "home"]

    def test_due_at_converted_to_utc(self, svc, repo):
        eastern = timezone(timedelta(hours=-5))
        due = datetime(2025, 7, 1, 12, 0, tzinfo=eastern)
        task = svc.create("t", due_at=due)
        assert task.due_at.tzinfo == timezone.utc


