"""Tests for InMemoryTaskRepository."""

from datetime import datetime, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.repository import InMemoryTaskRepository, normalize_tags


@pytest.fixture
def repo():
    return InMemoryTaskRepository()


def _task(id: int = 1, title: str = "Test") -> Task:
    return Task(id=id, title=title,
                created_at=datetime(2025, 1, 1, tzinfo=timezone.utc))


class TestInMemoryTaskRepository:
    def test_add_and_get(self, repo):
        t = _task()
        repo.add(t)
        assert repo.get(1) == t

    def test_get_missing_returns_none(self, repo):
        assert repo.get(99) is None

    def test_add_duplicate_raises(self, repo):
        repo.add(_task(1))
        with pytest.raises(ValueError, match="already exists"):
            repo.add(_task(1))

    def test_list_returns_all(self, repo):
        repo.add(_task(1))
        repo.add(_task(2, "Second"))
        result = list(repo.list())
        assert len(result) == 2

    def test_update(self, repo):
        repo.add(_task(1))
        updated = _task(1, "Updated")
        repo.update(updated)
        assert repo.get(1).title == "Updated"

    def test_update_missing_raises(self, repo):
        with pytest.raises(KeyError):
            repo.update(_task(99))

    def test_delete(self, repo):
        repo.add(_task(1))
        assert repo.delete(1) is True
        assert repo.get(1) is None

    def test_delete_missing_returns_false(self, repo):
        assert repo.delete(99) is False

    def test_next_id_increments(self, repo):
        assert repo.next_id() == 1
        assert repo.next_id() == 2
        assert repo.next_id() == 3


class TestNormalizeTags:
    def test_deduplicates(self):
        result = normalize_tags(["work", "Work", "WORK"])
        assert len(result) == 1
        assert result[0].name == "work"

    def test_preserves_order(self):
        result = normalize_tags(["beta", "alpha"])
        assert [t.name for t in result] == ["beta", "alpha"]

    def test_handles_tag_objects(self):
        result = normalize_tags([Tag("hello"), "Hello"])
        assert len(result) == 1

    def test_empty_input(self):
        assert normalize_tags([]) == []
